  ctx.fill();

  /* narrow helmet with cyan visor */
  const head = ctx.createLinearGradient(5, -4, 10, 4);
  head.addColorStop(0, '#eef5f8');
  head.addColorStop(0.55, '#b9cbd6');
  head.addColorStop(1, '#7690a1');
  ctx.fillStyle = head;
  ctx.beginPath();
  ctx.moveTo(5.2, -3.6);
  ctx.quadraticCurveTo(8.2, -4.3, 10.9, -2.3);
  ctx.lineTo(12.0, 0);
  ctx.lineTo(10.9, 2.3);
  ctx.quadraticCurveTo(8.2, 4.3, 5.2, 3.6);
  ctx.quadraticCurveTo(4.4, 0, 5.2, -3.6);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = '#547487';
  ctx.lineWidth = 0.65;
  ctx.stroke();

  ctx.save();
  ctx.shadowColor = 'rgba(133, 238, 255, 0.95)';
  ctx.shadowBlur = 4;
  ctx.fillStyle = 'rgba(178, 244, 255, 0.95)';
  ctx.beginPath();
  ctx.ellipse(9.15, 0, 1.35, 2.35, 0, 0, TAU);
  ctx.fill();
  ctx.restore();
  ctx.fillStyle = '#0d3646';
  ctx.beginPath();
  ctx.ellipse(9.4, 0, 0.55, 1.75, 0, 0, TAU);
  ctx.fill();

  // crown stripe and rim light
  ctx.strokeStyle = 'rgba(104, 194, 232, 0.9)';
  ctx.lineWidth = 0.6;
  ctx.beginPath();
  ctx.moveTo(5.8, 0);
  ctx.lineTo(10.2, 0);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.7)';
  ctx.lineWidth = 0.5;
  ctx.beginPath();
  ctx.arc(-1.0, 0, 4.8, -2.4, -1.1);
  ctx.stroke();
}

/* —— Kamino · Aiwhas ————————————————————————————————————
   Large grey-blue gliding whale with a broad manta-like wingspan,
   a pale belly stripe and a long forked tail. */
function drawAiwhasBody(ctx, e, time) {
  const p = e.phase || 0;
  const flap = Math.sin(time * 3.4 + p);
  const drift = Math.sin(time * 1.5 + p * 0.7);
  const tail = Math.sin(time * 2.5 + p);

  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  /* long tail with a forked fluke */
  const tailGrad = ctx.createLinearGradient(-12, 0, -34, 0);
  tailGrad.addColorStop(0, '#748fa4');
  tailGrad.addColorStop(0.6, '#5b778e');
  tailGrad.addColorStop(1, '#3f5b70');
  ctx.fillStyle = tailGrad;
  ctx.beginPath();
  ctx.moveTo(-11, -4.6);
  ctx.quadraticCurveTo(-22, -2.4 + tail * 1.6, -31, -2.6 + tail * 4.0);
  ctx.quadraticCurveTo(-28, 0, -31, 2.6 + tail * 4.0);
  ctx.quadraticCurveTo(-22, 2.4 + tail * 1.6, -11, 4.6);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(36, 60, 78, 0.85)';
  ctx.lineWidth = 0.7;
  ctx.stroke();

  // fluke lobes
  ctx.fillStyle = '#516e84';
  for (const side of [-1, 1]) {
    ctx.beginPath();
    ctx.moveTo(-30, side * 1.4 + tail * 4.0);
    ctx.quadraticCurveTo(-36, side * 5.4 + tail * 5.2, -38.5, side * 8.8 + tail * 5.6);
    ctx.quadraticCurveTo(-33, side * 5.4 + tail * 4.6, -29, side * 3.2 + tail * 4.2);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(30, 52, 68, 0.7)';
    ctx.lineWidth = 0.5;
    ctx.stroke();
  }

  /* wide gliding wings */
  for (const side of [-1, 1]) {
    const span = 1 + flap * 0.06;
    ctx.save();
    ctx.translate(1.5, 0);
    ctx.rotate(side * flap * 0.055);
    const wing = ctx.createLinearGradient(0, 0, -10, side * 26 * span);
    wing.addColorStop(0, '#a3bccd');
    wing.addColorStop(0.42, '#7e9bae');
    wing.addColorStop(0.78, '#5b768b');
    wing.addColorStop(1, '#3d576b');
    ctx.fillStyle = wing;
    ctx.beginPath();
    ctx.moveTo(7.0, side * 4.0);
    ctx.quadraticCurveTo(4.0, side * 13.0, -3.0, side * 21.0 * span);
    ctx.quadraticCurveTo(-8.0, side * 25.0 * span, -10.2, side * 22.0 * span);
    ctx.quadraticCurveTo(-14.0, side * 16.0, -17.0, side * 8.0);
    ctx.quadraticCurveTo(-12.5, side * 5.0, -9.0, side * 4.2);
    ctx.quadraticCurveTo(-2.0, side * 3.4, 7.0, side * 4.0);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(40, 66, 84, 0.8)';
    ctx.lineWidth = 0.75;
    ctx.stroke();

    // membrane ribs
    ctx.strokeStyle = 'rgba(198, 224, 240, 0.32)';
    ctx.lineWidth = 0.42;
    for (let k = 0; k < 4; k++) {
      const t = 0.25 + k * 0.19;
      ctx.beginPath();
      ctx.moveTo(3.0 - k * 1.2, side * (4.6 + k * 0.9));
      ctx.quadraticCurveTo(-6.0 - k * 1.4, side * (12 + k * 2.6), -8.5 - k * 1.8, side * (20 + k * 1.4) * span);
      ctx.stroke();
    }
    // pale leading edge
    ctx.strokeStyle = 'rgba(226, 244, 252, 0.55)';
    ctx.lineWidth = 0.6;
    ctx.beginPath();
    ctx.moveTo(7.0, side * 4.0);
    ctx.quadraticCurveTo(3.0, side * 12.5, -3.4, side * 20.5 * span);
    ctx.stroke();
    ctx.restore();
  }

  /* streamlined body */
  const body = ctx.createLinearGradient(-10, 0, 14, 0);
  body.addColorStop(0, '#547188');
  body.addColorStop(0.36, '#8ba7ba');
  body.addColorStop(0.72, '#a9c1cf');
  body.addColorStop(1, '#7f9bad');
  ctx.fillStyle = body;
  ctx.beginPath();
  ctx.moveTo(13.8, 0);
  ctx.quadraticCurveTo(11.5, -5.4, 3.0, -6.4);
  ctx.quadraticCurveTo(-5.0, -6.0, -11.0, -4.0);
  ctx.quadraticCurveTo(-13.5, 0, -11.0, 4.0);
  ctx.quadraticCurveTo(-5.0, 6.0, 3.0, 6.4);
  ctx.quadraticCurveTo(11.5, 5.4, 13.8, 0);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(43, 68, 86, 0.85)';
  ctx.lineWidth = 0.8;
  ctx.stroke();

  // pale belly stripe
  const belly = ctx.createLinearGradient(-9, 0, 12, 0);
  belly.addColorStop(0, 'rgba(224, 238, 246, 0)');
  belly.addColorStop(0.5, 'rgba(224, 238, 246, 0.5)');
  belly.addColorStop(1, 'rgba(232, 244, 250, 0.9)');
  ctx.fillStyle = belly;
  ctx.beginPath();
  ctx.ellipse(0.5, 0, 9.6, 2.9, 0, 0, TAU);
  ctx.fill();

  // head ridge and blowhole
  ctx.strokeStyle = 'rgba(52, 82, 102, 0.75)';
  ctx.lineWidth = 0.65;
  ctx.beginPath();
  ctx.moveTo(5.6, -4.6);
  ctx.quadraticCurveTo(9.5, -3.2, 11.8, 0);
  ctx.quadraticCurveTo(9.5, 3.2, 5.6, 4.6);
  ctx.stroke();
  ctx.fillStyle = 'rgba(36, 62, 80, 0.9)';
  ctx.beginPath();
  ctx.ellipse(3.4, 0, 1.0, 0.7, 0, 0, TAU);
  ctx.fill();

  // jaw line and eyes
  ctx.strokeStyle = 'rgba(36, 60, 78, 0.9)';
  ctx.lineWidth = 0.7;
  ctx.beginPath();
  ctx.moveTo(13.2, 0);
  ctx.quadraticCurveTo(10.6, 3.4, 6.4, 3.4);
  ctx.stroke();
  for (const side of [-1, 1]) {
    ctx.fillStyle = '#f1f7fb';
    ctx.beginPath();
    ctx.ellipse(9.3, side * 4.15, 1.15, 0.8, side * 0.2, 0, TAU);
    ctx.fill();
    ctx.fillStyle = '#173240';
    ctx.beginPath();
    ctx.ellipse(9.5, side * 4.15, 0.55, 0.55, 0, 0, TAU);
    ctx.fill();
  }

  // back mottling
  ctx.fillStyle = 'rgba(58, 92, 114, 0.35)';
  for (let i = 0; i < 6; i++) {
    const x = -8 + i * 3.3;
    ctx.beginPath();
    ctx.ellipse(x + drift * 0.15, (i % 2 ? 1.4 : -1.4), 1.0, 0.55, 0.4, 0, TAU);
    ctx.fill();
  }

  // gliding highlight
  ctx.strokeStyle = 'rgba(236, 248, 253, 0.5)';
  ctx.lineWidth = 0.55;
  ctx.beginPath();
  ctx.arc(0.5, 0, 5.6, -2.1, -0.9);
  ctx.stroke();
}

/* —— Kamino · Giant Sea Monster ——————————————————————————
   A massive dark-blue leviathan: four broad flippers, a long
   whipping tail, armoured back ridges and glowing yellow eyes. */
function drawSeaMonsterBody(ctx, e, time) {
  const p = e.phase || 0;
  const swim = Math.sin(time * 3.2 + p);
  const swimB = Math.sin(time * 3.2 + p + 1.7);
  const tailWave = Math.sin(time * 2.6 + p);
  const pulse = 0.72 + Math.sin(time * 3.4 + p) * 0.28;

  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  /* long tapering tail */
  const N = 16;
  const upper = [];
  const lower = [];
  for (let i = 0; i <= N; i++) {
    const t = i / N;
    const x = -13 - 47 * t;
    const cy = Math.sin(time * 2.6 + p + t * 3.2) * 8.5 * t * t;
    const w = 8.4 * Math.pow(1 - t, 0.72) + 0.8;
    upper.push([x, cy - w]);
    lower.push([x, cy + w]);
  }
  const tailGrad = ctx.createLinearGradient(-14, 0, -58, 0);
  tailGrad.addColorStop(0, '#2f6f9b');
  tailGrad.addColorStop(0.55, '#225madd'.replace('madd', '7a8'));
  tailGrad.addColorStop(1, '#0c2b42');
  ctx.fillStyle = tailGrad;
  ctx.beginPath();
  ctx.moveTo(upper[0][0], upper[0][1]);
  for (let i = 1; i <= N; i++) ctx.lineTo(upper[i][0], upper[i][1]);
  for (let i = N; i >= 0; i--) ctx.lineTo(lower[i][0], lower[i][1]);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(6, 24, 38, 0.9)';
  ctx.lineWidth = 1.1;
  ctx.stroke();

  // tail fluke
  const tipX = -59;
  const tipY = Math.sin(time * 2.6 + p + 3.2) * 8.5;
  ctx.fillStyle = '#1d4d70';
  for (const side of [-1, 1]) {
    ctx.beginPath();
    ctx.moveTo(tipX + 3, tipY);
    ctx.quadraticCurveTo(tipX - 3, tipY + side * 7, tipX - 7, tipY + side * 12);
    ctx.quadraticCurveTo(tipX - 1, tipY + side * 6, tipX + 5, tipY + side * 2.6);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(6, 24, 38, 0.75)';
    ctx.lineWidth = 0.7;
    ctx.stroke();
  }

  /* four broad flippers */
  const flippers = [
    { x: 9, y: -11, tx: 27, ty: -27, s: swim, len: 1.0 },
    { x: 9, y: 11, tx: 27, ty: 27, s: swimB, len: 1.0 },
    { x: -8, y: -9.5, tx: -15, ty: -22, s: swimB, len: 0.78 },
    { x: -8, y: 9.5, tx: -15, ty: 22, s: swim, len: 0.78 },
  ];
  for (const f of flippers) {
    const dx = f.tx - f.x;
    const dy = f.ty - f.y;
    const len = Math.hypot(dx, dy);
    const ang = Math.atan2(dy, dx) + f.s * 0.1;
    ctx.save();
    ctx.translate(f.x, f.y);
    ctx.rotate(ang);
    const wg = ctx.createLinearGradient(0, 0, len, 0);
    wg.addColorStop(0, '#2a638a');
    wg.addColorStop(0.7, '#1d4a6b');
    wg.addColorStop(1, '#113451');
    ctx.fillStyle = wg;
    ctx.beginPath();
    ctx.moveTo(0, -3.6 * f.len);
    ctx.quadraticCurveTo(len * 0.55, -6.4 * f.len, len, -0.6);
    ctx.quadraticCurveTo(len * 1.02, 0.6, len * 0.96, 1.6);
    ctx.quadraticCurveTo(len * 0.55, 6.2 * f.len, 0, 3.6 * f.len);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(5, 22, 36, 0.85)';
    ctx.lineWidth = 0.9;
    ctx.stroke();
    // paddle ridges
    ctx.strokeStyle = 'rgba(120, 178, 210, 0.32)';
    ctx.lineWidth = 0.5;
    for (let k = -1; k <= 1; k++) {
      ctx.beginPath();
      ctx.moveTo(len * 0.1, k * 1.8 * f.len);
      ctx.quadraticCurveTo(len * 0.55, k * 3.8 * f.len, len * 0.9, k * 1.1);
      ctx.stroke();
    }
    ctx.restore();
  }

  /* massive muscular body */
  const body = ctx.createRadialGradient(2, -3, 4, 0, 0, 30);
  body.addColorStop(0, '#3f85b2');
  body.addColorStop(0.42, '#255f88');
  body.addColorStop(0.78, '#143e5d');
  body.addColorStop(1, '#0a2438');
  ctx.fillStyle = body;
  ctx.beginPath();
  ctx.moveTo(28.5, 0);
  ctx.quadraticCurveTo(27.5, -11.5, 16.0, -16.6);
  ctx.quadraticCurveTo(1.0, -20.5, -12.5, -11.5);
  ctx.quadraticCurveTo(-17.5, -5.5, -17.0, 0);
  ctx.quadraticCurveTo(-17.5, 5.5, -12.5, 11.5);
  ctx.quadraticCurveTo(1.0, 20.5, 16.0, 16.6);
  ctx.quadraticCurveTo(27.5, 11.5, 28.5, 0);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = '#061c2c';
  ctx.lineWidth = 1.5;
  ctx.stroke();

  // pectoral / flank musculature
  ctx.strokeStyle = 'rgba(120, 184, 216, 0.3)';
  ctx.lineWidth = 0.9;
  for (const side of [-1, 1]) {
    ctx.beginPath();
    ctx.moveTo(12, side * 6.5);
    ctx.quadraticCurveTo(4, side * 12.5, -7, side * 9.5);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(14, side * 2.5);
    ctx.quadraticCurveTo(5, side * 4.5, -3, side * 3.5);
    ctx.stroke();
  }

  // pale underbelly wedge
  const belly = ctx.createLinearGradient(0, 10, 0, -10);
  belly.addColorStop(0, 'rgba(122, 180, 208, 0.34)');
  belly.addColorStop(0.5, 'rgba(122, 180, 208, 0.08)');
  belly.addColorStop(1, 'rgba(122, 180, 208, 0.34)');
  ctx.fillStyle = belly;
  ctx.beginPath();
  ctx.ellipse(-1, 0, 17.5, 7.2, 0, 0, TAU);
  ctx.fill();

  /* armoured dorsal ridge */
  for (let i = 0; i < 7; i++) {
    const x = -9 + i * 5.0;
    const s = 1 - i * 0.07;
    ctx.fillStyle = i % 2 ? '#2a5f83' : '#37769e';
    ctx.beginPath();
    ctx.moveTo(x - 3.2 * s, 0);
    ctx.lineTo(x, -3.4 * s);
    ctx.lineTo(x + 3.2 * s, 0);
    ctx.lineTo(x, 3.4 * s);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(8, 30, 46, 0.55)';
    ctx.lineWidth = 0.45;
    ctx.stroke();
  }

  /* broad head and jaw */
  const head = ctx.createLinearGradient(18, -12, 34, 12);
  head.addColorStop(0, '#3a7ba6');
  head.addColorStop(0.55, '#215879');
  head.addColorStop(1, '#0e3148');
  ctx.fillStyle = head;
  ctx.beginPath();
  ctx.moveTo(19.5, -11.0);
  ctx.quadraticCurveTo(29.0, -10.0, 32.5, -3.5);
  ctx.lineTo(34.0, 0);
  ctx.lineTo(32.5, 3.5);
  ctx.quadraticCurveTo(29.0, 10.0, 19.5, 11.0);
  ctx.quadraticCurveTo(16.5, 0, 19.5, -11.0);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = '#051a29';
  ctx.lineWidth = 1.1;
  ctx.stroke();

  // snout highlight and nostrils
  ctx.strokeStyle = 'rgba(150, 210, 236, 0.4)';
  ctx.lineWidth = 0.9;
  ctx.beginPath();
  ctx.moveTo(22, -8.2);
  ctx.quadraticCurveTo(29, -5.6, 31.5, -1.2);
  ctx.stroke();
  ctx.fillStyle = 'rgba(4, 20, 32, 0.85)';
  for (const side of [-1, 1]) {
    ctx.beginPath();
    ctx.ellipse(30.4, side * 2.2, 1.2, 0.7, side * 0.2, 0, TAU);
    ctx.fill();
  }

  // jaw line and teeth
  ctx.strokeStyle = 'rgba(4, 18, 30, 0.95)';
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(33.2, 0);
  ctx.quadraticCurveTo(29.5, 8.4, 20.5, 9.6);
  ctx.stroke();
  ctx.fillStyle = '#e8eee4';
  for (let i = 0; i < 6; i++) {
    const t = i / 5;
    const x = 32.4 - t * 10.4;
    const y = 1.0 + t * 7.4;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x - 1.1, y + 1.1);
    ctx.lineTo(x + 0.5, y + 1.4);
    ctx.closePath();
    ctx.fill();
  }

  // glowing yellow eyes
  for (const side of [-1, 1]) {
    ctx.save();
    ctx.shadowColor = 'rgba(255, 214, 70, 0.95)';
    ctx.shadowBlur = 10 * pulse;
    ctx.fillStyle = `rgba(255, 224, 104, ${0.88 + pulse * 0.12})`;
    ctx.beginPath();
    ctx.ellipse(24.6, side * 8.0, 2.9, 1.8, side * 0.24, 0, TAU);
    ctx.fill();
    ctx.restore();
    ctx.fillStyle = '#1b1405';
    ctx.beginPath();
    ctx.ellipse(25.2, side * 8.0, 0.85, 1.55, 0, 0, TAU);
    ctx.fill();
    ctx.fillStyle = 'rgba(255, 255, 220, 0.9)';
    ctx.beginPath();
    ctx.arc(24.4, side * 7.5, 0.5, 0, TAU);
    ctx.fill();
  }

  // brow ridges over the eyes
  ctx.strokeStyle = 'rgba(10, 36, 54, 0.9)';
  ctx.lineWidth = 1.6;
  for (const side of [-1, 1]) {
    ctx.beginPath();
    ctx.moveTo(21.0, side * 9.8);
    ctx.quadraticCurveTo(24.4, side * 11.2, 28.2, side * 8.8);
    ctx.stroke();
  }

  // scarred flank detail
  ctx.strokeStyle = 'rgba(160, 210, 232, 0.26)';
  ctx.lineWidth = 0.7;
  ctx.beginPath();
  ctx.moveTo(-4, -8.5);
  ctx.lineTo(2, -6.8);
  ctx.lineTo(6, -8.0);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(-8, 6.5);
  ctx.lineTo(-2, 8.0);
  ctx.stroke();

  // bioluminescent spots along the flanks
  ctx.fillStyle = 'rgba(122, 226, 255, 0.55)';
  for (const side of [-1, 1]) {
    for (let i = 0; i < 4; i++) {
      ctx.beginPath();
      ctx.arc(-12 + i * 6.5, side * 13.2, 0.75, 0, TAU);
      ctx.fill();
    }
  }

  // shifting surface highlight
  ctx.strokeStyle = 'rgba(198, 236, 252, 0.34)';
  ctx.lineWidth = 0.85;
  ctx.beginPath();
  ctx.arc(1.5, 0, 12.5, -2.5, -1.0);
  ctx.stroke();
}

