import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.mjs';
const browser = await chromium.launch({headless:true, executablePath:'/home/runner/.cache/ms-playwright/chromium-1255/chrome-linux64/chrome', args:['--no-sandbox']});
const page = await browser.newPage({viewport:{width:1280,height:800}, deviceScaleFactor:1});
const errors=[];
page.on('pageerror', e => errors.push(e.message));
await page.goto('http://localhost:3000/',{waitUntil:'networkidle'});
await page.locator('#playBtn').click();
await page.locator('#chooseMapBtn').click();
await page.locator('[data-map="kamino"]').click();
await page.locator('#mapDockPlayBtn').click();
const placement = await page.evaluate(() => {
  const g = window.__game;
  const pad = {x:0.06,y:0.93};
  const water = {x:0.70,y:0.88};
  const route = {x:0.455,y:0.37};
  const checks = {
    pad: g.canPlace('scout',pad.x,pad.y),
    openWater: g.canPlace('scout',water.x,water.y),
    enemyBridge: g.canPlace('scout',route.x,route.y),
  };
  const placedPad = checks.pad.ok ? g.placeTower('scout',pad.x,pad.y) : null;
  const placedWater = checks.openWater.ok ? g.placeTower('scout',water.x,water.y) : null;
  return {checks, placedPad, placedWater, towers:g.towers.map(t=>({type:t.type,nx:t.nx,ny:t.ny}))};
});
const waves = await page.evaluate(() => {
  const g = window.__game;
  const seen = {};
  const report = [];
  for (let wave=1; wave<=25; wave++) {
    if (!g.startWave()) throw new Error(`Could not start wave ${wave}`);
    const types = [...new Set(g.spawnQueue.map(s=>s.type))];
    report.push({wave,types});
    if ([1,7,13,25].includes(wave)) seen[wave]=types;
    if (wave === 25) {
      const spec = g.spawnQueue.find(s=>s.type==='seamonster');
      if (!spec) throw new Error('Final wave has no sea monster');
      g.spawnEnemy(spec);
      seen.boss = {type:g.bossRef?.type,isBoss:g.bossRef?.isBoss,hp:g.bossRef?.hp};
    }
    g.completeWave();
  }
  return {milestones:seen,finalPhase:g.phase,finalWave:g.waveNumber};
});
console.log(JSON.stringify({placement,waves,errors},null,2));
await browser.close();
